import { MainWrapper, PhotoFrame, HedWrapper, Headline, Subheadline, ContentWrapper } from "./index.stitches";

function Topper() {
  return (
    <header>
      <MainWrapper>
        <ContentWrapper>
          <HedWrapper>
          <PhotoFrame>

          </PhotoFrame>
          <Headline><span>Hi, I’m</span> Agnes!</Headline>
          </HedWrapper>
          <Subheadline>
            I am currently a D.C.-based Designer at The Washington Post, where I
            design and develop interactive stories.
          </Subheadline>
        </ContentWrapper>
      </MainWrapper>
    </header>
  );
}

export default Topper;
